const rows = $input.all();
let text = 'No previous conversation history. This is a new conversation.';

if (rows.length > 0) {
  const ordered = [...rows].reverse();
  text = 'Recent conversation history with this customer:\n' + ordered.map(r => `- Customer: ${r.json.user_message}\n- Bot: ${r.json.bot_reply}`).join('\n');
}

return [{
  json: {
    conversationHistory: text,
    chatId: $('Extract Message Data').first().json.chatId,
    sessionId: $('Extract Message Data').first().json.sessionId,
    from: $('Extract Message Data').first().json.from,
    userMessage: $('Extract Message Data').first().json.userMessage
  }
}];

const rows = $input.all();

// 1. Verify if the client exists in the database at all
const isKnownClient = rows.length > 0 && rows[0].json.email !== undefined;

// 2. Verify if they actually have orders (handling the LEFT JOIN nulls)
const hasOrders = rows.length > 0 && rows[0].json.order_id !== null && rows[0].json.order_id !== undefined;

// 3. Extract the client info from the first row
const clientInfo = {
  isKnownClient: isKnownClient,
  clientEmail: isKnownClient ? rows[0].json.email : 'None',
  clientName: isKnownClient ? (rows[0].json.full_name || 'None') : 'None',
  companyName: isKnownClient ? (rows[0].json.company_name || 'None') : 'None',
  clientType: isKnownClient ? (rows[0].json.client_type || 'regular') : 'regular'
}

// 4. Build the order summary
let summary = 'No prior order history found for this number.';
if (hasOrders) {
  summary = 'This customer has prior orders:\n' + rows.map(r => 
    `- Order ${r.json.order_id}: ${r.json.product_name} x${r.json.quantity}, status: ${r.json.order_status}, date: ${r.json.order_date}`
  ).join('\n');
}

// 5. Output the combined context
return [{ 
  json: { 
    customerType: hasOrders ? 'returning' : 'new',
    clientInfo: clientInfo,
    ordersSummary: summary 
  } 
}];

return [
  { json: { fileName: 'customer_qnas.csv', filePath: '/data/kb/customer_qnas.csv', kbType: 'embed', sourceLabel: 'faq' } },
  { json: { fileName: 'product_info.csv', filePath: '/data/kb/product_info.csv', kbType: 'embed', sourceLabel: 'product' } },
  { json: { fileName: 'b2b_playbook.csv', filePath: '/data/kb/aim_green_master.csv', kbType: 'embed', sourceLabel: 'b2b' } },
  { json: { fileName: 'order_data.csv', filePath: '/data/kb/order_data.csv', kbType: 'relational', sourceLabel: 'orders' } }
];

// Turns each CSV row into a text chunk + metadata for embedding.
// Handles both customer_qnas.csv (Category, Question, Answer, Reference_URL)
// and product_info.csv (product_name, category, description, price, sku, availability).
const items = $input.all();
const out = [];

for (const item of items) {
  const row = item.json;
  let pageContent = '';

  if (row.Question || row.question) {
    const q = row.Question || row.question;
    const a = row.Answer || row.answer;
    const cat = row.Category || row.category || '';
    pageContent = `Category: ${cat}\nQ: ${q}\nA: ${a}`;
  } else if (row.product_name) {
    pageContent = `Product: ${row.product_name}\nCategory: ${row.category || ''}\nDescription: ${row.description || ''}\nPrice: ${row.price || ''}\nSKU: ${row.sku || ''}\nAvailability: ${row.availability || ''}`;
  } else {
    // Fallback: dump all columns
    pageContent = Object.entries(row).map(([k, v]) => `${k}: ${v}`).join('\n');
  }

  out.push({
    json: {
      pageContent,
      metadata: { source: $('Define KB File List').first().json.fileName, sourceLabel: $('Define KB File List').first().json.sourceLabel }
    }
  });
}

return out;

const items = $input.all();

for (let i = 0; i < items.length; i++) {
